import zipfile
import xml.etree.ElementTree as ET

def extract_xlsx(file_path):
    try:
        with zipfile.ZipFile(file_path) as z:
            # First, read sharedStrings.xml if it exists
            shared_strings = []
            try:
                ss_content = z.read('xl/sharedStrings.xml')
                root = ET.fromstring(ss_content)
                for elem in root.iter():
                    if elem.tag.endswith('t'):
                        shared_strings.append(elem.text or "")
            except KeyError:
                pass

            # Now, let's look for sheet files
            sheets = []
            for name in z.namelist():
                if name.startswith('xl/worksheets/sheet'):
                    sheets.append(name)

            output = []
            for sheet in sheets:
                output.append(f"=== Sheet: {sheet} ===")
                sheet_content = z.read(sheet)
                root = ET.fromstring(sheet_content)
                # Parse rows and cells
                for row in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
                    row_data = []
                    for cell in row.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
                        val_elem = cell.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v')
                        val = ""
                        if val_elem is not None:
                            val = val_elem.text or ""

                        # Check cell type
                        t = cell.get('t')
                        if t == 's' and val != "":
                            idx = int(val)
                            if idx < len(shared_strings):
                                val = shared_strings[idx]
                        row_data.append(val)
                    if any(row_data):
                        output.append("\t".join(row_data))
            return "\n".join(output)
    except Exception as e:
        return f"Error reading {file_path}: {e}"

if __name__ == '__main__':
    print(extract_xlsx('Due Diligence/AIAG Financial Statements 2025 (1).xlsx'))
